-- =====================================================================
--  BROS Planbord — databasescript 007: Meetstaat in het Planbord
--  Postenbibliotheek (loten + posten), meetstaatregels per project,
--  vorderingsstaat (facturatie). Alleen toevoegingen; mag opnieuw uitgevoerd worden.
--  Vóór uitvoeren: Supabase → Database → Backups.
-- =====================================================================

-- ---------- Loten (hoofdstukken van de meetstaat, zoals het sjabloon) ----------
create table if not exists public.loten (
  nr            int primary key,
  naam          text not null,
  buildwise     text not null default '',
  standaard_aan boolean not null default true,
  vakman        text not null default '',
  marge         numeric(6,4) not null default 0,      -- standaardmarge, 0.15 = 15 %
  actief        boolean not null default true
);

-- ---------- Postenbibliotheek ----------
create table if not exists public.posten (
  id            uuid primary key default gen_random_uuid(),
  code          text not null default '',
  lot           int not null references public.loten(nr),
  groep         text not null default '',
  omschrijving  text not null,
  eenheid       text not null default 'stk',
  prijstype     text not null default 'EP' check (prijstype in ('EP','SOG','BUDGET')),
  buildwise     text not null default '',
  richtprijs    numeric(12,2),
  prijs_min     numeric(12,2),
  prijs_max     numeric(12,2),
  n             int not null default 0,
  marge         numeric(6,4),                            -- null = marge van het lot
  btw           numeric(4,2) not null default 0.06,
  standaard_aan boolean not null default false,
  per_ruimte    boolean not null default false,
  actief        boolean not null default true,
  vakman        text not null default '',
  opmerking     text not null default '',
  volgorde      int not null default 0,
  updated_at    timestamptz not null default now()
);
create index if not exists posten_lot_idx on public.posten(lot, volgorde);

-- ---------- Meetstaatregels per project ----------
create table if not exists public.meetstaat_posten (
  id            uuid primary key default gen_random_uuid(),
  project_id    uuid not null references public.projecten(id) on delete cascade,
  post_id       uuid references public.posten(id) on delete set null,
  lot           int not null references public.loten(nr),
  code          text not null default '',
  groep         text not null default '',
  omschrijving  text not null,
  locatie       text not null default '',
  eenheid       text not null default 'stk',
  prijstype     text not null default 'EP',
  hoeveelheid   numeric(12,3) not null default 0,
  eenheidsprijs numeric(12,2) not null default 0,       -- kostprijs / aannemersprijs excl. btw
  marge         numeric(6,4),                            -- null = marge van het lot
  btw           numeric(4,2) not null default 0.06,
  status        text not null default 'offerte' check (status in ('offerte','akkoord','meerwerk','minwerk','vervallen')),
  vakman        text not null default '',
  te_bestellen  boolean not null default false,
  besteld       boolean not null default false,
  leverdatum    date,
  geleverd      boolean not null default false,
  leverancier   text not null default '',
  artikelnr     text not null default '',
  opmerking     text not null default '',
  volgorde      int not null default 0,
  created_by    uuid references public.profiles(id),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index if not exists meetstaat_posten_project_idx on public.meetstaat_posten(project_id, lot, volgorde);

-- ---------- Vorderingsstaat / facturatie ----------
create table if not exists public.vorderingen (
  id             uuid primary key default gen_random_uuid(),
  project_id     uuid not null references public.projecten(id) on delete cascade,
  nr             int not null default 1,                 -- 0 = voorschot
  soort          text not null default 'vordering' check (soort in ('voorschot','vordering','slotfactuur','meerwerk')),
  omschrijving   text not null default '',
  datum          date,
  factuurnummer  text not null default '',               -- Yuki
  bedrag_excl    numeric(12,2),                           -- gefactureerd bedrag excl. btw (nakijken tegen berekening)
  status         text not null default 'opgemaakt' check (status in ('opgemaakt','verzonden','betaald')),
  opmerking      text not null default '',
  created_at     timestamptz not null default now()
);
create index if not exists vorderingen_project_idx on public.vorderingen(project_id, nr);

create table if not exists public.vordering_regels (   -- % per lot per vordering (cumulatief)
  vordering_id   uuid not null references public.vorderingen(id) on delete cascade,
  lot            int not null references public.loten(nr),
  pct            numeric(6,4) not null default 0,       -- 0.30 = 30 % van het lot in deze schijf
  primary key (vordering_id, lot)
);

-- ---------- Rechten ----------
alter table public.loten enable row level security;
alter table public.posten enable row level security;
alter table public.meetstaat_posten enable row level security;
alter table public.vorderingen enable row level security;
alter table public.vordering_regels enable row level security;
drop policy if exists loten_select on public.loten;   create policy loten_select on public.loten for select to authenticated using (true);
drop policy if exists loten_beheer on public.loten;   create policy loten_beheer on public.loten for all to authenticated using (public.is_beheer()) with check (public.is_beheer());
drop policy if exists posten_select on public.posten; create policy posten_select on public.posten for select to authenticated using (true);
drop policy if exists posten_beheer on public.posten; create policy posten_beheer on public.posten for all to authenticated using (public.is_beheer()) with check (public.is_beheer());
drop policy if exists mp_all on public.meetstaat_posten; create policy mp_all on public.meetstaat_posten for all to authenticated using (true) with check (true);
drop policy if exists vord_all on public.vorderingen; create policy vord_all on public.vorderingen for all to authenticated using (true) with check (true);
drop policy if exists vordr_all on public.vordering_regels; create policy vordr_all on public.vordering_regels for all to authenticated using (true) with check (true);

do $$
declare t text;
begin
  foreach t in array array['loten','posten','meetstaat_posten','vorderingen','vordering_regels'] loop
    if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end $$;

